namespace Overclock {
 sealed class MetricCard:Control {
  public string Title="",Primary="—",Unit="",Device="",Secondary="",Footnote="",RingText="—";public float Level=-1;public float[] Series=new float[0];public Color Accent=Theme.Accent;public StorageCapacity Capacity;
  Bitmap deviceGlow;string deviceGlowKey="";int glowPadding;
  public MetricCard(){DoubleBuffered=true;BackColor=Theme.Background;Cursor=Cursors.Hand;AccessibleRole=AccessibleRole.PushButton;}
  public void Set(string title,string primary,string unit,string device,string secondary,string footnote,float level,string ring,float[] series){string signature=title+primary+unit+device+secondary+footnote+level+ring+string.Join(",",series.Select(x=>x.ToString("0.0")).ToArray())+(Capacity==null?"":Capacity.VolumeBytes+"/"+Capacity.FreeBytes);if(Tag as string==signature)return;Tag=signature;Title=title;Primary=primary;Unit=unit;Device=device;Secondary=secondary;Footnote=footnote;Level=level;RingText=ring;Series=series;AccessibleName=title+" "+device+" "+primary+unit+" "+secondary;Invalidate();}
  void TextAt(Graphics g,string value,float size,Rectangle rectangle,Color color,bool bold=false){TextRenderer.DrawText(g,value,Theme.Face(size,bold?FontStyle.Bold:FontStyle.Regular),rectangle,color,TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding);}
  void Ring(Graphics g,Rectangle rectangle){using(var pen=new Pen(Theme.Line,5))g.DrawArc(pen,rectangle,0,360);if(Level>=0)using(var pen=new Pen(Accent,5){StartCap=LineCap.Round,EndCap=LineCap.Round})g.DrawArc(pen,rectangle,-90,Math.Max(1,Math.Min(100,Level)*3.6f));TextRenderer.DrawText(g,RingText,Theme.Face(11,FontStyle.Bold),rectangle,Theme.Text,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
  void DeviceName(Graphics g,Rectangle rectangle){using(var path=new GraphicsPath())using(var format=new StringFormat{Trimming=StringTrimming.EllipsisWord,FormatFlags=StringFormatFlags.LineLimit}){float size=14;while(size>11&&g.MeasureString(Device,Theme.Face(size,FontStyle.Bold),rectangle.Width).Height>rectangle.Height)size--;path.AddString(Device,Theme.Face(size).FontFamily,(int)FontStyle.Bold,size*g.DpiY/72,rectangle,format);string key=Device+"/"+rectangle.Size+"/"+size+"/"+g.DpiY;if(deviceGlow==null||deviceGlowKey!=key){if(deviceGlow!=null)deviceGlow.Dispose();glowPadding=(int)Math.Ceiling(15*g.DpiY/96);deviceGlow=SoftNeon.Create(path,rectangle,glowPadding,g.DpiY/96);deviceGlowKey=key;}g.DrawImageUnscaled(deviceGlow,rectangle.X-glowPadding,rectangle.Y-glowPadding);using(var brush=new SolidBrush(Color.FromArgb(255,248,249)))g.FillPath(brush,path);}}
  protected override void Dispose(bool disposing){if(disposing&&deviceGlow!=null){deviceGlow.Dispose();deviceGlow=null;}base.Dispose(disposing);}
  void History(Graphics g,int top,int height,int pad){if(Series.Length<2)return;using(var pen=new Pen(Theme.Line))for(int i=0;i<3;i++)g.DrawLine(pen,pad,top+i*height/2,Width-pad,top+i*height/2);using(var pen=new Pen(Accent,2))for(int i=1;i<Series.Length;i++)g.DrawLine(pen,pad+(i-1)*(Width-pad*2f)/(Series.Length-1),top+height-Math.Min(100,Series[i-1])*height/100,pad+i*(Width-pad*2f)/(Series.Length-1),top+height-Math.Min(100,Series[i])*height/100);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Theme.Round(new RectangleF(0,0,Width-1,Height-1),14)){using(var brush=new LinearGradientBrush(ClientRectangle,Theme.Raised,Theme.Surface,35))g.FillPath(brush,path);using(var pen=new Pen(Theme.Line))g.DrawPath(pen,path);}bool small=Height<145;int pad=small?14:22;TextAt(g,Title.ToUpperInvariant(),9,new Rectangle(pad,pad,Width-pad*2,20),Accent,true);
   if(small){bool name=Height>118&&(Title=="CPU"||Title=="GPU");if(name)TextAt(g,Device,10,new Rectangle(pad,34,Width-pad*2,24),Color.FromArgb(255,210,215),true);int y=name?62:32;TextAt(g,Primary,22,new Rectangle(pad,y,Width-pad*2-70,34),Theme.Text,true);TextAt(g,Unit,9,new Rectangle(pad,y+37,Width-pad*2-70,20),Theme.Muted);Ring(g,new Rectangle(Width-pad-54,y,54,54));return;}
   if(Title=="Storage"&&Capacity!=null){DrawStorage(g,pad);return;}
   bool hardware=Title=="CPU"||Title=="GPU";int primaryY=hardware?pad+78:pad+28;int width=Math.Max(70,Width-pad*2-90);if(hardware)DeviceName(g,new Rectangle(pad,pad+26,Width-pad*2,50));int ringSize=hardware?64:76;Ring(g,new Rectangle(Width-pad-ringSize,primaryY+7,ringSize,ringSize));TextAt(g,Primary,Primary.Length>4?24:32,new Rectangle(pad,primaryY,width,56),Theme.Text,true);TextAt(g,Unit,10,new Rectangle(pad,primaryY+54,width,21),Theme.Muted);if(!hardware)TextAt(g,Device,10,new Rectangle(pad,pad+115,Width-pad*2,24),Theme.Text);TextAt(g,Secondary,9,new Rectangle(pad,hardware?pad+153:pad+141,Width-pad*2,24),Theme.Muted);if(Height>250)History(g,Height-66,28,pad);TextAt(g,Footnote,8,new Rectangle(pad,Height-25,Width-pad*2,20),Theme.Muted);
  }
  void DrawStorage(Graphics g,int pad){bool dense=Height<310;TextAt(g,StorageFormat.Size(Capacity.PhysicalBytes),30,new Rectangle(pad,50,Width-pad*2,52),Theme.Text,true);TextAt(g,"installed internal storage",10,new Rectangle(pad,dense?100:106,Width-pad*2,24),Theme.Muted);int y=dense?128:148;int w=Width-pad*2;using(var brush=new SolidBrush(Theme.Line))g.FillRectangle(brush,pad,y,w,9);if(Capacity.PhysicalBytes>0&&Capacity.VolumeCount>0){float used=(float)Math.Min(1,Capacity.UsedBytes/(double)Capacity.PhysicalBytes),free=(float)Math.Min(1-used,Capacity.FreeBytes/(double)Capacity.PhysicalBytes);using(var brush=new SolidBrush(Theme.AccentSoft))g.FillRectangle(brush,pad,y,w*used,9);using(var brush=new SolidBrush(Theme.Secondary))g.FillRectangle(brush,pad+w*used,y,w*free,9);TextAt(g,"Used "+StorageFormat.Size(Capacity.UsedBytes),9,new Rectangle(pad,y+18,w/2,22),Theme.AccentSoft);TextAt(g,"Free "+StorageFormat.Size(Capacity.FreeBytes),9,new Rectangle(pad+w/2,y+18,w/2,22),Theme.Secondary);}else TextAt(g,"Volume free space unavailable",9,new Rectangle(pad,y+18,w,22),Theme.Muted);
   var drives=Capacity.Disks.OrderBy(d=>d.MediaType=="SSD"?0:1).ThenBy(d=>d.Number).ToList();int start=y+48,line=dense?19:23;int count=Math.Min(drives.Count,Math.Max(1,(Height-start-27)/line));for(int i=0;i<count;i++)TextAt(g,"#"+drives[i].Number+"  "+drives[i].Name,9,new Rectangle(pad,start+i*line,w,line),Theme.Text);string note=count<drives.Count?"+ "+(drives.Count-count)+" additional drive · Open details →":Capacity.OtherBytes>1073741824?StorageFormat.Size(Capacity.OtherBytes)+" other / unmounted · Details →":"Physical drives · Open details →";TextAt(g,note,8,new Rectangle(pad,Height-24,w,20),Theme.Muted);
  }
 }
 static class SoftNeon {
  public static Bitmap Create(GraphicsPath glyphs,Rectangle bounds,int padding,float scale){int width=bounds.Width+padding*2,height=bounds.Height+padding*2;float[] alpha=new float[width*height];using(var mask=new Bitmap(width,height,PixelFormat.Format32bppArgb)){using(var graphics=Graphics.FromImage(mask))using(var local=(GraphicsPath)glyphs.Clone())using(var transform=new Matrix()){graphics.Clear(Color.Transparent);graphics.SmoothingMode=SmoothingMode.AntiAlias;transform.Translate(padding-bounds.X,padding-bounds.Y);local.Transform(transform);graphics.FillPath(Brushes.White,local);}var pixels=mask.LockBits(new Rectangle(0,0,width,height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{byte[] bytes=new byte[pixels.Stride*height];Marshal.Copy(pixels.Scan0,bytes,0,bytes.Length);for(int y=0;y<height;y++)for(int x=0;x<width;x++)alpha[y*width+x]=bytes[y*pixels.Stride+x*4+3];}finally{mask.UnlockBits(pixels);}}
   var wide=Blur(alpha,width,height,4.2f*scale);var core=Blur(alpha,width,height,1.6f*scale);var bitmap=new Bitmap(width,height,PixelFormat.Format32bppArgb);var data=bitmap.LockBits(new Rectangle(0,0,width,height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{byte[] bytes=new byte[data.Stride*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int pixel=y*width+x,offset=y*data.Stride+x*4;bytes[offset]=84;bytes[offset+1]=58;bytes[offset+2]=255;bytes[offset+3]=(byte)Math.Min(115,wide[pixel]*.58f+core[pixel]*.20f);}Marshal.Copy(bytes,0,data.Scan0,bytes.Length);}finally{bitmap.UnlockBits(data);}return bitmap;
  }
  static float[] Blur(float[] source,int width,int height,float sigma){int radius=(int)Math.Ceiling(sigma*3);float[] kernel=new float[radius*2+1];double total=0;for(int i=-radius;i<=radius;i++){kernel[i+radius]=(float)Math.Exp(-(i*i)/(2*sigma*sigma));total+=kernel[i+radius];}for(int i=0;i<kernel.Length;i++)kernel[i]/=(float)total;var horizontal=new float[source.Length];var result=new float[source.Length];for(int y=0;y<height;y++)for(int x=0;x<width;x++){float value=0;for(int i=-radius;i<=radius;i++)if(x+i>=0&&x+i<width)value+=source[y*width+x+i]*kernel[i+radius];horizontal[y*width+x]=value;}for(int y=0;y<height;y++)for(int x=0;x<width;x++){float value=0;for(int i=-radius;i<=radius;i++)if(y+i>=0&&y+i<height)value+=horizontal[(y+i)*width+x]*kernel[i+radius];result[y*width+x]=value;}return result;}
 }
}
